<?php
$connection=db();$stats=$connection->query("SELECT (SELECT COUNT(*) FROM products WHERE status='active') products,(SELECT COUNT(*) FROM orders WHERE status IN ('new','confirmed','processing','ready')) open_orders,(SELECT COUNT(*) FROM products WHERE stock_quantity<=reorder_level) low_stock,COALESCE((SELECT SUM(total_amount) FROM orders WHERE status='completed'),0) revenue")->fetch_assoc();$orders=$connection->query("SELECT o.*,GROUP_CONCAT(CONCAT(oi.quantity,' × ',oi.product_name) SEPARATOR ', ') items FROM orders o LEFT JOIN order_items oi ON oi.order_id=o.id GROUP BY o.id ORDER BY o.created_at DESC LIMIT 12")->fetch_all(MYSQLI_ASSOC);$lowStock=$connection->query('SELECT name,stock_quantity FROM products WHERE stock_quantity<=reorder_level ORDER BY stock_quantity,name LIMIT 5')->fetch_all(MYSQLI_ASSOC);$success=flash('success');$error=flash('error');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sammy Tech | Workspace</title><link rel="stylesheet" href="../assets/css/admin.css"></head><body><div class="admin-layout"><aside><a class="admin-brand" href="index.php"><span>ST</span> SAMMY TECH</a><p class="aside-label">Operations</p><a class="side-active" href="index.php">Overview</a><a href="catalog.php">Catalog</a><a href="reports.php">Reports</a><a href="installations.php">Installations</a><a href="../index.php" target="_blank">View storefront ↗</a><form class="logout" action="logout.php" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><button>Sign out</button></form></aside><main class="admin-main"><header><div><p class="eyebrow">Operations dashboard</p><h1>Good day, team.</h1></div><a class="add-link" href="catalog.php">+ Add product</a></header><?php if($success):?><p class="notice success"><?=e($success)?></p><?php endif;?><?php if($error):?><p class="notice error"><?=e($error)?></p><?php endif;?><section class="stat-grid"><article><span>Active products</span><strong><?=e((string)$stats['products'])?></strong></article><article><span>Open orders</span><strong><?=e((string)$stats['open_orders'])?></strong></article><article><span>Low stock items</span><strong><?=e((string)$stats['low_stock'])?></strong></article><article><span>Completed revenue</span><strong><?=money((float)$stats['revenue'])?></strong></article></section><section class="panel"><div class="panel-title"><h2>Incoming orders</h2><span>Confirming deducts stock</span></div><div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Items</th><th>Total</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($orders as $order):?><tr><td><b><?=e($order['order_number'])?></b><small><?=e(date('d M, H:i',strtotime($order['created_at'])))?></small></td><td><?=e($order['customer_name'])?><small><?=e($order['phone'])?></small></td><td class="items"><?=e($order['items']?:'—')?></td><td><?=money((float)$order['total_amount'])?></td><td><span class="status status-<?=e($order['status'])?>"><?=e($order['status'])?></span><small>Payment: <?=e($order['payment_status'])?></small></td><td><form class="status-form" action="order_action.php" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="order_id" value="<?=e((string)$order['id'])?>"><input type="hidden" name="action" value="status"><select name="status"><?php foreach(['new','confirmed','processing','ready','completed','cancelled'] as $status):?><option value="<?=$status?>" <?=$order['status']===$status?'selected':''?>><?=ucfirst($status)?></option><?php endforeach;?></select><button>Save</button></form><form class="status-form" action="order_action.php" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="order_id" value="<?=e((string)$order['id'])?>"><input type="hidden" name="action" value="payment"><select name="payment_status"><?php foreach(['pending','paid','failed','refunded'] as $payment):?><option value="<?=$payment?>" <?=$order['payment_status']===$payment?'selected':''?>><?=ucfirst($payment)?></option><?php endforeach;?></select><button>Payment</button></form></td></tr><?php endforeach;?></tbody></table></div></section><section class="stock-panel"><div><p class="eyebrow">Attention needed</p><h2>Low stock watch</h2></div><div><?php foreach($lowStock as $product):?><p><b><?=e($product['name'])?></b><span><?=e((string)$product['stock_quantity'])?> left</span></p><?php endforeach;?></div></section></main></div></body></html>
